672	def validate_survey(obj):
673	    """Validate a decoded survey payload.
674	
675	    Returns (clean_survey, None) on success or (None, error_message) on failure.
676	    Strings are stored trimmed of surrounding whitespace; description keeps its
677	    raw value so Chinese, quotes and newlines are preserved.
678	    """
679	    if not isinstance(obj, dict):
680	        return None, "请求体必须是 JSON 对象"
681	    if "title" not in obj:
682	        return None, "缺少字段 title"
683	    title = obj["title"]
684	    if not isinstance(title, str):
685	        return None, "title 必须是字符串"
686	    title = title.strip()
687	    if not title:
688	        return None, "title 不能为空（或全为空白字符）"
689	
690	    description = obj.get("description", "")
691	    if not isinstance(description, str):
692	        return None, "description 必须是字符串"
693	
694	    if "questions" not in obj:
695	        return None, "缺少字段 questions"
696	    raw_questions = obj["questions"]
697	    if not isinstance(raw_questions, list):
698	        return None, "questions 必须是数组"
699	    if len(raw_questions) == 0:
700	        return None, "questions 至少需要一道题"
701	
702	    questions = []
703	    for index, raw_question in enumerate(raw_questions, start=1):
704	        location = f"第 {index} 题"
705	        if not isinstance(raw_question, dict):
706	            return None, f"{location}（questions[{index - 1}]）必须是对象"
707	
708	        if "type" not in raw_question:
709	            return None, f"{location}：缺少字段 type"
710	        question_type = raw_question["type"]
711	        if not isinstance(question_type, str):
712	            return None, f"{location}：type 必须是字符串"
713	        if question_type not in QUESTION_TYPES:
714	            shown = json.dumps(question_type, ensure_ascii=False)
715	            return None, f"{location}：不支持的题型 {shown}（仅支持 text 或 single_choice）"
716	
717	        if "title" not in raw_question:
718	            return None, f"{location}：缺少字段 title"
719	        question_title = raw_question["title"]
720	        if not isinstance(question_title, str):
721	            return None, f"{location}：title 必须是字符串"
722	        question_title = question_title.strip()
723	        if not question_title:
724	            return None, f"{location}：题目标题不能为空（或全为空白字符）"
725	
726	        required = raw_question.get("required", False)
727	        if not isinstance(required, bool):
728	            return None, f"{location}：required 必须是布尔值"
729	
730	        raw_options = raw_question.get("options", [])
731	        if not isinstance(raw_options, list):
732	            return None, f"{location}：options 必须是数组"
733	
734	        options = []
735	        if question_type == "text":
736	            if len(raw_options) > 0:
737	                return None, f"{location}：文本题不能包含选项（options 必须省略或为空数组）"
738	        else:
739	            if len(raw_options) < 2:
740	                return None, f"{location}：单选题至少需要两个选项"
741	            seen = set()
742	            for option_index, raw_option in enumerate(raw_options, start=1):
743	                if not isinstance(raw_option, str):
744	                    return None, f"{location}：第 {option_index} 个选项必须是字符串"
745	                option = raw_option.strip()
746	                if not option:
747	                    return None, f"{location}：第 {option_index} 个选项不能为空（或全为空白字符）"
748	                if option in seen:
749	                    shown = json.dumps(option, ensure_ascii=False)
750	                    return None, f"{location}：选项 {shown} 重复（同一题内选项不得重复）"
751	                seen.add(option)
752	                options.append(option)
753	
754	        questions.append({
755	            "type": question_type,
756	            "title": question_title,
757	            "required": required,
758	            "options": options,
759	        })
760	
761	    return {
762	        "title": title,
763	        "description": description,
764	        "questions": questions,
765	    }, None
