768	def main():
769	    parser = argparse.ArgumentParser(description="OpenSurvey - 问卷调查与反馈管理")
770	    commands = parser.add_subparsers(dest="command", required=True)
771	    serve = commands.add_parser("serve", help="Start the HTTP service")
772	    serve.add_argument("--host", default="127.0.0.1", help="Address to bind (default: 127.0.0.1)")
773	    serve.add_argument("--port", type=int, default=8080, help="Port to bind; 0 selects an available port")
774	    serve.add_argument("--data-dir", type=Path, default=Path("data"), help="Directory for the local SQLite database")
775	    args = parser.parse_args()
776	    if not 0 <= args.port <= 65535:
777	        parser.error("port must be between 0 and 65535")
778	    args.data_dir.mkdir(parents=True, exist_ok=True)
779	    # 每个连接由独立线程处理（见下方 ThreadingHTTPServer），因此数据库连接
780	    # 会被多个线程共享：check_same_thread=False 允许跨线程使用，所有读写再
781	    # 经 db_lock 串行化，保证一次保存/替换内部的多条语句仍然原子生效。
782	    database = sqlite3.connect(args.data_dir / "open-survey.sqlite", check_same_thread=False)
783	    db_lock = threading.Lock()
784	    database.execute("CREATE TABLE IF NOT EXISTS surveys (id INTEGER PRIMARY KEY, title TEXT NOT NULL)")
785	    columns = {row[1] for row in database.execute("PRAGMA table_info(surveys)")}
786	    if "description" not in columns:
787	        database.execute("ALTER TABLE surveys ADD COLUMN description TEXT NOT NULL DEFAULT ''")
788	    database.execute(
789	        "CREATE TABLE IF NOT EXISTS questions ("
790	        "id INTEGER PRIMARY KEY, survey_id INTEGER NOT NULL, position INTEGER NOT NULL, "
791	        "type TEXT NOT NULL, title TEXT NOT NULL, required INTEGER NOT NULL)"
792	    )
793	    database.execute(
794	        "CREATE TABLE IF NOT EXISTS question_options ("
795	        "id INTEGER PRIMARY KEY, question_id INTEGER NOT NULL, position INTEGER NOT NULL, text TEXT NOT NULL)"
796	    )
797	    database.commit()
798	
799	    def survey_detail(survey_id):
800	        with db_lock:
801	            row = database.execute(
802	                "SELECT title, COALESCE(description, '') FROM surveys WHERE id = ?",
803	                (survey_id,),
804	            ).fetchone()
805	            if row is None:
806	                return None
807	            title, description = row
808	            questions = []
809	            question_rows = database.execute(
810	                "SELECT id, type, title, required FROM questions WHERE survey_id = ? ORDER BY position",
811	                (survey_id,),
812	            ).fetchall()
813	            for question_id, question_type, question_title, required in question_rows:
814	                options = [option_row[0] for option_row in database.execute(
815	                    "SELECT text FROM question_options WHERE question_id = ? ORDER BY position",
816	                    (question_id,),
817	                )]
818	                questions.append({
819	                    "type": question_type,
820	                    "title": question_title,
821	                    "required": bool(required),
822	                    "options": options,
823	                })
824	        return {
825	            "id": survey_id,
826	            "title": title,
827	            "description": description,
828	            "questions": questions,
829	        }
830	
831	    def save_survey(clean):
832	        """Insert the whole survey atomically; returns the new id."""
833	        with db_lock:
834	            try:
835	                cursor = database.execute(
836	                    "INSERT INTO surveys (title, description) VALUES (?, ?)",
837	                    (clean["title"], clean["description"]),
838	                )
839	                survey_id = cursor.lastrowid
840	                write_questions(survey_id, clean["questions"])
841	                database.commit()
842	                return survey_id
843	            except Exception:
844	                database.rollback()
845	                raise
846	
847	    def write_questions(survey_id, questions):
848	        """Replace all questions/options of a survey with the given ordered list."""
849	        old_question_ids = [row[0] for row in database.execute(
850	            "SELECT id FROM questions WHERE survey_id = ?", (survey_id,)
851	        )]
852	        if old_question_ids:
853	            placeholders = ",".join("?" for _ in old_question_ids)
854	            database.execute(
855	                f"DELETE FROM question_options WHERE question_id IN ({placeholders})",
856	                old_question_ids,
857	            )
858	        database.execute("DELETE FROM questions WHERE survey_id = ?", (survey_id,))
859	        for position, question in enumerate(questions):
860	            question_cursor = database.execute(
861	                "INSERT INTO questions (survey_id, position, type, title, required) "
862	                "VALUES (?, ?, ?, ?, ?)",
863	                (survey_id, position, question["type"], question["title"],
864	                 1 if question["required"] else 0),
865	            )
866	            question_id = question_cursor.lastrowid
867	            for option_position, option in enumerate(question["options"]):
868	                database.execute(
869	                    "INSERT INTO question_options (question_id, position, text) VALUES (?, ?, ?)",
870	                    (question_id, option_position, option),
871	                )
872	
873	    def replace_survey(survey_id, clean):
874	        """Replace a whole survey atomically; keeps the same id.
875	
876	        Returns False when the survey does not exist (no record is created).
877	        """
878	        with db_lock:
879	            row = database.execute("SELECT 1 FROM surveys WHERE id = ?", (survey_id,)).fetchone()
880	            if row is None:
881	                return False
882	            try:
883	                database.execute(
884	                    "UPDATE surveys SET title = ?, description = ? WHERE id = ?",
885	                    (clean["title"], clean["description"], survey_id),
886	                )
887	                write_questions(survey_id, clean["questions"])
888	                database.commit()
889	                return True
890	            except Exception:
891	                database.rollback()
892	                raise
