894	    class Handler(BaseHTTPRequestHandler):
895	        def respond(self, status, value, *, html=False, allow=None):
896	            payload = value.encode("utf8") if html else json.dumps(value, ensure_ascii=False).encode("utf8")
897	            self.send_response(status)
898	            self.send_header("Content-Type", "text/html; charset=utf-8" if html else "application/json; charset=utf-8")
899	            self.send_header("Content-Length", str(len(payload)))
900	            if status == 405 and allow is not None:
901	                self.send_header("Allow", ", ".join(allow))
902	            self.end_headers()
903	            self.wfile.write(payload)
904	
