906	            with db_lock:
907	                records = [
908	                    {"id": row[0], "title": row[1]}
909	                    for row in database.execute("SELECT id, title FROM surveys ORDER BY id")
910	                ]
911	            self.respond(200, {RESOURCE: records})
912	
913	        def read_payload(self):
914	            """Read and decode a JSON request body.
915	
916	            Returns (payload, None) or (None, error_message).
917	            """
918	            try:
919	                length = int(self.headers.get("Content-Length") or 0)
920	            except ValueError:
921	                length = -1
922	            if length < 0:
923	                return None, "Content-Length 无效"
924	            if length > MAX_BODY_BYTES:
925	                return None, "请求体过大"
926	            body = self.rfile.read(length) if length else b""
927	            try:
928	                return json.loads(body.decode("utf8")), None
929	            except (UnicodeDecodeError, json.JSONDecodeError) as error:
930	                return None, f"请求体不是合法 JSON：{error}"
