952	            if survey_detail(survey_id) is None:
953	                # Editing a missing id is always 404 and must never create one.
954	                self.respond(404, {"error": "not found"})
955	                return
956	            if read_error is not None:
957	                self.respond(400, {"error": read_error})
958	                return
959	
960	            # Full replacement: validate before touching the stored draft so a
961	            # rejected request leaves the old survey exactly as it was.
962	            clean, error = validate_survey(payload)
963	            if error is not None:
