function route() {
  const editMatch = location.hash.match(/^#\/surveys\/(\d+)\/edit$/);
  const detailMatch = location.hash.match(/^#\/surveys\/(\d+)$/);
  if (editMatch) renderEdit(Number(editMatch[1]));
